"""Current posting and preserved E-invoice-reference report; no reconciliation."""
from create_pysb_historical_invoice_drafts import Run
from inspect_pysb_historical_invoices import OUT
from execute_pysb_stock_migration import index,rid,require,save
from collections import Counter
import json,html
def main():
 m=Run();manifest=json.loads((OUT/'invoice-draft-manifest.json').read_text(encoding='utf8'));e=json.loads((OUT/'einvoice-reference-reconciliation.json').read_text(encoding='utf8'));einvoices=index([{'id':r['source_id'],**r} for r in e['rows']]);docs=manifest['documents'];ids=[m.j['documents'][str(d['source_id'])]['target_id'] for d in docs];moves=index(m.b.read('account.move',ids,['name','state','company_id','move_type','invoice_date','date','invoice_date_due','amount_total','x_studio_v14_refererce','x_submission_uid','x_my_einvoice_longid','x_my_einvoice_link_to_portal','x_validation_time','x_einvoice_state']));rows=[]
 for d in docs:
  v=moves[m.j['documents'][str(d['source_id'])]['target_id']];require(abs(v['amount_total']-d['source']['amount_total'])<0.00501 and v['date']==d['source']['date'] and v['invoice_date']==d['source']['invoice_date'],'Dates/amount mismatch');require(all(v[k]==einvoices[d['source_id']][k] for k in ['x_submission_uid','x_my_einvoice_longid','x_my_einvoice_link_to_portal','x_validation_time','x_einvoice_state']),'E-invoice metadata mismatch');rows.append({'source_id':d['source_id'],'source_name':d['source_name'],'target_id':v['id'],**v})
 summary={'database':m.b.db,'company_id':1,'documents':len(rows),'states':dict(Counter(v['state'] for v in rows)),'types_states':dict(Counter(v['move_type']+'/'+v['state'] for v in rows)),'dates_and_amounts_match':True,'einvoice_reference_verified':e['summary'],'account_remap_status':m.j.get('approved_posting_account_remap',{}).get('status'),'payments_reconciliation_bank_matching':'deferred, not performed'};save(OUT/'invoice-posting-current-report.json',{'summary':summary,'rows':rows,'pending':[r for r in rows if r['state']!='posted']});save(OUT/'invoice-next-step-handoff.json',{'summary':summary,'rows':rows,'pending':[r for r in rows if r['state']!='posted'],'deferred_credit_notes':manifest['deferred_documents'],'stage':m.j['stage']})
 labels=['Tham chiếu v14','Số chứng từ v19','Trạng thái','Ngày hóa đơn','Ngày kế toán','Tổng tiền','E-invoice UUID/reference','LongId','MyInvois'];fields=['source_name','name','state','invoice_date','date','amount_total','x_submission_uid','x_my_einvoice_longid','x_einvoice_state'];body=''.join('<tr>'+''.join('<td>'+html.escape(str(r[k] or ''))+'</td>' for k in fields)+'</tr>' for r in rows);states=summary['states'];page='<meta charset="utf-8"><title>Pao Yeang — Invoice/Bill và E-invoice reference</title><style>body{font:14px Arial;margin:24px}table{border-collapse:collapse}td,th{border:1px solid #ddd;padding:6px}th{background:#eef4fa}</style><h1>Pao Yeang — Invoice/Bill lịch sử</h1><p>Đã post '+str(states.get('posted',0))+'/1057; còn '+str(states.get('draft',0))+' bản nháp. Ngày và số tiền khớp nguồn. E-invoice metadata đã đối chiếu 1057/1057: 834 có UUID/reference, 833 có LongId; những trường nguồn trống được giữ trống. Không gửi lại e-invoice.</p><p>Ánh xạ tài khoản archived sang cấu hình v19 theo Bruce; không sửa tài khoản hoặc sản phẩm. Các chứng từ chưa có cấu hình giữ ở nháp. Payment, reconcile và bank statement để bước sau.</p><table><tr>'+''.join('<th>'+x+'</th>' for x in labels)+'</tr>'+body+'</table>'; (OUT/'PYSB_Invoice_Bill_Posting_Review.html').write_text(page,encoding='utf8');print(json.dumps(summary,ensure_ascii=False))
if __name__=='__main__':main()
